using System;
using System.Collections.Generic;
using Framework.Grid;
using UnityEngine;

namespace Framework.Pathfinding
{
    /// <summary>
    /// グリッドマップ上の最短経路を探索する。
    /// </summary>
    /// <remarks>
    /// A*アルゴリズムを使用する。
    /// 上下左右の4方向移動に対応し、
    /// 各セル間の移動コストは1とする。
    /// </remarks>
    public static class GridPathfinder
    {
        /// <summary>
        /// 経路探索で使用する移動方向。
        /// </summary>
        private static readonly Vector2Int[] Directions =
        {
            Vector2Int.up,
            Vector2Int.down,
            Vector2Int.left,
            Vector2Int.right
        };

        /// <summary>
        /// 開始地点から目的地までの最短経路を探索する。
        /// </summary>
        /// <typeparam name="T">セルのデータ型</typeparam>
        /// <param name="map">探索対象のグリッドマップ</param>
        /// <param name="start">開始地点</param>
        /// <param name="goal">目的地</param>
        /// <param name="canEnterCell">セルの通行可能条件</param>
        /// <param name="path">探索された経路</param>
        /// <returns>経路が見つかった場合はtrue</returns>
        /// <remarks>
        /// 経路には開始地点と目的地の両方を含む。
        /// 探索に失敗した場合は空のリストを返す。
        /// 探索中にマップや通行可能条件を変更しないこと。
        /// </remarks>
        public static bool TryFindPath<T>(
            GridMap<T> map,
            Vector2Int start,
            Vector2Int goal,
            Func<Vector2Int, bool> canEnterCell,
            out List<Vector2Int> path)
        {
            path = new List<Vector2Int>();

            // 依存関係を検証する。
            if (map == null || canEnterCell == null)
            {
                return false;
            }

            // 開始地点と目的地の範囲を確認する。
            if (!map.IsInside(start) ||
                !map.IsInside(goal))
            {
                return false;
            }

            // 開始地点と目的地が通行可能か確認する。
            if (!canEnterCell(start) ||
                !canEnterCell(goal))
            {
                return false;
            }

            // 開始地点と目的地が同一の場合。
            if (start == goal)
            {
                path.Add(start);

                return true;
            }

            // 今後探索する候補セル。
            var openSet = new List<Vector2Int>();

            // 探索が完了したセル。
            var closedSet = new HashSet<Vector2Int>();

            // 各セルへ到達する直前のセル。
            var cameFrom =
                new Dictionary<Vector2Int, Vector2Int>();

            // 開始地点から各セルまでの移動コスト。
            var gScores =
                new Dictionary<Vector2Int, int>();

            openSet.Add(start);
            gScores[start] = 0;

            while (openSet.Count > 0)
            {
                // 推定総コストが最小のセルを選択する。
                int currentIndex = GetBestNodeIndex(
                    openSet,
                    gScores,
                    goal);

                Vector2Int current =
                    openSet[currentIndex];

                // 目的地に到達した場合は経路を復元する。
                if (current == goal)
                {
                    ReconstructPath(
                        cameFrom,
                        current,
                        path);

                    return true;
                }

                openSet.RemoveAt(currentIndex);
                closedSet.Add(current);

                // 隣接する4方向のセルを探索する。
                foreach (Vector2Int direction in Directions)
                {
                    Vector2Int neighbor =
                        current + direction;

                    if (!map.IsInside(neighbor) ||
                        closedSet.Contains(neighbor) ||
                        !canEnterCell(neighbor))
                    {
                        continue;
                    }

                    // 隣接セルへの移動コストは1とする。
                    int tentativeGScore =
                        gScores[current] + 1;

                    bool hasPreviousScore =
                        gScores.TryGetValue(
                            neighbor,
                            out int previousGScore);

                    // 既存経路より短くない場合は更新しない。
                    if (hasPreviousScore &&
                        tentativeGScore >= previousGScore)
                    {
                        continue;
                    }

                    cameFrom[neighbor] = current;
                    gScores[neighbor] = tentativeGScore;

                    // 未登録の候補セルを追加する。
                    if (!hasPreviousScore)
                    {
                        openSet.Add(neighbor);
                    }
                }
            }

            // 目的地まで到達できなかった。
            return false;
        }

        /// <summary>
        /// 開始地点から目的地までの最短経路距離を取得する。
        /// </summary>
        /// <typeparam name="T">セルのデータ型</typeparam>
        /// <param name="map">探索対象のマップ</param>
        /// <param name="start">開始地点</param>
        /// <param name="goal">目的地</param>
        /// <param name="canEnterCell">セルの通行可能条件</param>
        /// <returns>
        /// 最短経路距離。到達不能の場合は-1。
        /// </returns>
        public static int GetShortestDistance<T>(
            GridMap<T> map,
            Vector2Int start,
            Vector2Int goal,
            Func<Vector2Int, bool> canEnterCell)
        {
            if (!TryFindPath(
                    map,
                    start,
                    goal,
                    canEnterCell,
                    out List<Vector2Int> path))
            {
                return -1;
            }

            // 開始地点を除いた移動回数を返す。
            return path.Count - 1;
        }

        /// <summary>
        /// 2つの座標間のマンハッタン距離を取得する。
        /// </summary>
        /// <param name="from">開始座標</param>
        /// <param name="to">終了座標</param>
        /// <returns>上下左右の移動距離</returns>
        public static int GetManhattanDistance(
            Vector2Int from,
            Vector2Int to)
        {
            return Mathf.Abs(from.x - to.x) +
                   Mathf.Abs(from.y - to.y);
        }

        /// <summary>
        /// 推定総コストが最小の探索候補を取得する。
        /// </summary>
        /// <param name="openSet">探索候補一覧</param>
        /// <param name="gScores">各セルの移動コスト</param>
        /// <param name="goal">目的地</param>
        /// <returns>最適な探索候補のインデックス</returns>
        private static int GetBestNodeIndex(
            List<Vector2Int> openSet,
            Dictionary<Vector2Int, int> gScores,
            Vector2Int goal)
        {
            int bestIndex = 0;

            int bestHScore = GetManhattanDistance(
                openSet[0],
                goal);

            int bestFScore =
                gScores[openSet[0]] + bestHScore;

            for (int i = 1; i < openSet.Count; i++)
            {
                Vector2Int position = openSet[i];

                int hScore = GetManhattanDistance(
                    position,
                    goal);

                int fScore =
                    gScores[position] + hScore;

                // 総コストが同じ場合は目的地に近い方を優先する。
                if (fScore < bestFScore ||
                    (fScore == bestFScore &&
                     hScore < bestHScore))
                {
                    bestIndex = i;
                    bestFScore = fScore;
                    bestHScore = hScore;
                }
            }

            return bestIndex;
        }

        /// <summary>
        /// 探索結果から開始地点までの経路を復元する。
        /// </summary>
        /// <param name="cameFrom">各セルの直前座標</param>
        /// <param name="current">目的地の座標</param>
        /// <param name="path">復元先の経路リスト</param>
        private static void ReconstructPath(
            Dictionary<Vector2Int, Vector2Int> cameFrom,
            Vector2Int current,
            List<Vector2Int> path)
        {
            path.Clear();
            path.Add(current);

            // 目的地から開始地点まで逆順にたどる。
            while (cameFrom.TryGetValue(
                current,
                out Vector2Int previous))
            {
                current = previous;

                path.Add(current);
            }

            // 開始地点から目的地への順序に変換する。
            path.Reverse();
        }
    }
}
